        timer.Interval = TimeSpan.FromMilliseconds(16);
        timer.Tick += new EventHandler(Timer_Tick);
        timer.Start();
    }

    private void ResetButton_Click(object sender, RoutedEventArgs e)
    {
        timer.Stop();
        hours = 0;
        minutes = 0;
        seconds = 0;
        ResetTimerText();
    }

    private void Timer_Tick(object sender, EventArgs e)
    {
        seconds++;

        if (seconds >= 60)
        {
            seconds = 0;
            minutes++;
        }
        if (minutes >= 60)
        {
            minutes = 0;
            hours++;
        }
        ResetTimerText();
    }

    private void ResetTimerText()
    {
        TimerText.Text = $"{hours.ToString().PadLeft(2, '0')}:{minutes.ToString().PadLeft(2, '0')}:{seconds.ToString().PadLeft(2, '0')}";
    }
}
