Here's a basic implementation of the Aldous-Broder algorithm in JavaScript to generate a random maze, and then draw it on an HTML5 Canvas element.

```javascript
// Size of the maze
const WIDTH = 500;
const HEIGHT = 500;
const CELL_SIZE = 20;

// Create the canvas element
const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');

// Set the canvas dimensions
canvas.width = WIDTH;
canvas.height = HEIGHT;

// Generate a random maze
function generateMaze(width, height) {
  const maze = [];
  const directions = [[0, 1], [0, -1], [1, 0], [-1, 0]];
  for (let i = 0; i < width; i++) {
    maze[i] = [];
    for (let j = 0; j < height; j++) {
      maze[i][j] = Math.random() < 0.5? 1 : 0; // 1 for wall, 0 for path
    }
  }

  for (let i = 0; i < width * height; i++) {
    const directionIndex = Math.floor(Math.random() * directions.length);
    const direction = directions[directionIndex];
    const x = Math.floor(Math.random() * width);
    const y = Math.floor(Math.random() * height);
    while (maze[x][y] === 1) {
      x = Math.floor(Math.random() * width);
      y = Math.floor(Math.random() * height);
    }
    maze[x][y] = 1; // Mark the chosen cell as visited
    maze[x + direction[0]][y + direction[1]] = 0; // Carve a path
  }

  return maze;
}

// Draw the maze on the canvas
function drawMaze(maze) {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < maze.length; i++) {
    for (let j = 0; j < maze[i].length; j++) {
      if (maze[i][j] === 1) {
        ctx.fillStyle = 'black';
        ctx.fillRect(i * CELL_SIZE, j * CELL_SIZE, CELL_SIZE, CELL_SIZE);
      } else {
        ctx.fillStyle = 'white';
        ctx.fillRect(i * CELL_SIZE, j * CELL_SIZE, CELL_SIZE, CELL_SIZE);
      }
    }
  }
}

Here is the rest of the code to generate and draw the maze on the HTML Canvas element:

```javascript
// Generate the maze
const maze = generateMaze(WIDTH / CELL_SIZE, HEIGHT / CELL_SIZE);

// Draw the maze
drawMaze(maze);

// Start a timer
let timer = 0;

// Update and draw the maze at 60 frames per second
function update() {
  timer++;
  if (timer % 60 === 0) {
    drawMaze(maze);
  }
}

// Start the animation
setInterval(update, 1000 / 60);
```

