public class MyStringBuilder
{
    private char[] _buffer;
    private int _capacity;
    private int _length;

    public MyStringBuilder(int initialCapacity = 16)
    {
        _buffer = new char[initialCapacity];
        _capacity = initialCapacity;
        _length = 0;
    }

    public MyStringBuilder Append(char value)
    {
        if (_length >= _capacity)
        {
            Resize();
        }
        _buffer[_length++] = value;
        return this;
    }

    public MyStringBuilder Append(string value)
    {
        if (value == null) return this;
        for (int i = 0; i < value.Length; i++)
        {
            Append(value[i]);
        }
        return this;
    }

    public MyStringBuilder AppendFormat(string format, params object[] args)
    {
        if (format == null) return this;
        List<char> buffer = new List<char>(_buffer);
        buffer.AddRange(format.ToCharArray());
        for (int i = 0; i < args.Length; i++)
        {
            buffer.Add((args[i].ToString() + ((i < args.Length - 1)? " " : "")).ToCharArray()[0]);
        }
        _buffer = buffer.ToArray();
        _length = buffer.Count;
        return this;
    }

    public MyStringBuilder AppendLine(string value)
    {
        if (value == null) return this;
        Append(value);
        Append(Environment.NewLine);
        return this;
    }

    public override string ToString()
    {
        return new string(_buffer, 0, _length);
    }

    private void Resize()
    {
        _capacity *= 2;
        char[] newBuffer = new char[_capacity];
        Array.Copy(_buffer, 0, newBuffer, 0, _length);
        _buffer = newBuffer;
    }
}
