function getParams(url: string): { [key: string]: string } {
  const params: { [key: string]: string } = {};
  const query = url.split('?')[1]; // split the URL into path and query
  if (query) {
    const queryParts = query.split('&'); // split the query into individual param pairs
    queryParts.forEach((pair) => {
      const [key, value] = pair.split('=');
      params[key] = decodeURIComponent(value); // decode the value using encodeURIComponent
    });
  }
  return params;
}

