is_normal_distribution <- function(x) {
  # Check skewness
  skewness <- skewness(x)
  if (abs(skewness) > 1) {
    return(FALSE)
  }

  # Check kurtosis
  kurtosis <- kurtosis(x)
  if (abs(kurtosis - 3) > 1) {
    return(FALSE)
  }

  # Check histogram (Naive approach)
  hist(x, freq = FALSE, main = "Histogram")
  if (!grepl("bell-curve", grepl(hist(x, freq = FALSE))))
    return(FALSE)

  # Check Kolmogorov-Smirnov test
  result_kstest <- kstest(x, "pnorm")
  if (result_kstest$p.value > 0.05) {
    return(FALSE)
  }

  # Check Shapiro-Wilk test
  result_shapiro.test <- shapiro.test(x)
  if (result_shapiro.test$p.value > 0.05) {
    return(FALSE)
  }

  # If all conditions pass, return TRUE
  return(TRUE)
}
```
