```cpp
#include <Arduino.h>

const int LEFT_MOTOR_SPEED = 9; // Pin for setting speed for Left Motor
const int RIGHT_MOTOR_SPEED = 10; // Pin for setting speed for Right Motor
const int LEFT_MOTOR_DIR = 8; // Pin for controlling direction of Left Motor
const int RIGHT_MOTOR_DIR = 7; // Pin for controlling direction of Right Motor

int pwmSpeed = 128; // Set the initial speed to 50%

void setup() {
  pinMode(LEFT_MOTOR_SPEED, OUTPUT);
  pinMode(RIGHT_MOTOR_SPEED, OUTPUT);
  pinMode(LEFT_MOTOR_DIR, OUTPUT);
  pinMode(RIGHT_MOTOR_DIR, OUTPUT);
}

void driveForward() {
  digitalWrite(LEFT_MOTOR_DIR, HIGH);
  digitalWrite(RIGHT_MOTOR_DIR, HIGH);
  analogWrite(LEFT_MOTOR_SPEED, pwmSpeed);
  analogWrite(RIGHT_MOTOR_SPEED, pwmSpeed);
}

void driveReverse() {
  digitalWrite(LEFT_MOTOR_DIR, LOW);
  digitalWrite(RIGHT_MOTOR_DIR, LOW);
  analogWrite(LEFT_MOTOR_SPEED, pwmSpeed);
  analogWrite(RIGHT_MOTOR_SPEED, pwmSpeed);
}

void turnLeft() {
  digitalWrite(LEFT_MOTOR_DIR, HIGH);
  digitalWrite(RIGHT_MOTOR_DIR, HIGH);
  analogWrite(LEFT_MOTOR_SPEED, pwmSpeed);
  analogWrite(RIGHT_MOTOR_SPEED, 0);
}

void turnRight() {
  digitalWrite(LEFT_MOTOR_DIR, HIGH);
  digitalWrite(RIGHT_MOTOR_DIR, HIGH);
  analogWrite(LEFT_MOTOR_SPEED, 0);
  analogWrite(RIGHT_MOTOR_SPEED, pwmSpeed);
}

void stopMotor() {
  digitalWrite(LEFT_MOTOR_DIR, LOW);
  digitalWrite(RIGHT_MOTOR_DIR, LOW);
  analogWrite(LEFT_MOTOR_SPEED, 0);
  analogWrite(RIGHT_MOTOR_SPEED, 0);
}

void loop() {
  driveForward();
  delay(2000);
  stopMotor();
  delay(2000);
  driveReverse();
  delay(2000);
  stopMotor();
  delay(2000);
  turnLeft();
  delay(2000);
  stopMotor();
  delay(2000);

Here is the remaining part of the script:

