using System;
using System.Collections.Generic;

namespace TranslateProductName
{
    public class TranslateProductNamePlugin : IPlugin
    {
        public void Execute(IPluginExecutionContext context)
        {
            // Get the product entity and field
            var entity = context.GetParameter(EntityName.product);
            var field = entity.Attributes[FieldSchemaName.productname];

            // Get the translation service
            var translationService = new TranslationService(context.OrganizationService);

            // Get the product name translations
