            // Update the product name with the translated value
            entity.Attributes[FieldSchemaName.productname] = translationsTranslations[translationService.CurrentCulture].Value;

            // Save the entity
            context.OrganizationService.UpdateEntity(entity);
        }
    }

    public class TranslationService
    {
        private readonly IOrganizationService organizationService;
        private readonly string currentCulture;

        public TranslationService(IOrganizationService organizationService)
        {
            this.organizationService = organizationService;
            this.currentCulture = CultureInfo.CurrentCulture.TwoLetterISOLanguageName;
        }

        public ILocalizedFieldTranslations GetTranslations(IOrganizationServiceFactory serviceFactory, Entity entity, string fieldLogicalName)
