Yes, you can encrypt text with a key and output it as a string in C++. One common method is to use the Caesar Cipher, which replaces each letter with a letter a fixed number of positions down the alphabet. Here's an example:

```cpp
#include <iostream>
#include <string>
#include <cctype>

using namespace std;

string caesarCipher(string input, int key) {
    string output = "";
    for (char c : input) {
        if (isalpha(c)) {
            char base = isupper(c)? 'A' : 'a';
            output += (c + key - base) % 26 + base;
        } else {
            output += c;
        }
    }
    return output;
}

int main() {
    string input, keyStr;
    cout << "Enter the text to encrypt: ";
    getline(cin, input);
    cout << "Enter the key (1-25): ";
    getline(cin, keyStr);
    int key = stoi(keyStr);
    string output = caesarCipher(input, key);
    cout << "Encrypted text: " << output << endl;
    return 0;
}
```

This program will ask the user to input the text to encrypt and the key (a number between 1 and 25). It will then encrypt the text using the Caesar Cipher with the given key and print the result.

