#include<iostream>
using namespace std;

int main() {
    int arr[5];

    // Calculate and store factorial of each index
    for(int i = 0; i < 5; i++) {
        int fact = 1;
        for(int j = 1; j <= i; j++) {
            fact *= j;
        }
        arr[i] = fact;
    }

    // Print the array
    cout << "Array of factorials: ";
    for(int i = 0; i < 5; i++) {
        cout << arr[i] << " ";
    }

    return 0;
}
