To use the file upload controller from your Flutter app, you'll need to make an HTTP request to the API endpoint. Here's an example of how you can do this using the `http` package in Flutter:
```dart
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;

class FileUploadPage extends StatefulWidget {
  @override
  _FileUploadPageState createState() => _FileUploadPageState();
}

class _FileUploadPageState extends State<FileUploadPage> {
  final _formKey = GlobalKey<FormState>();
  File _file;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text('File Upload'),
      ),
      body: Padding(
        padding: const EdgeInsets.all(20.0),
        child: Form(
          key: _formKey,
          child: Column(
            children: [
              TextFormField(
                decoration: InputDecoration(labelText: 'Select file'),
                onChanged: (value) => _file = File(value),
              ),
              SizedBox(height: 20),
              ElevatedButton(
                onPressed: () {
                  if (_formKey.currentState.validate()) {
                    _formKey.currentState.save();
                    uploadFile();
                  }
                },
                child: Text('Upload file'),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Future<void> uploadFile() async {
    final url = 'https://your-dotnet-core-api.com/api/fileupload'; // Replace with your API URL
    final request = http.MultipartRequest('POST', Uri.parse(url));
    request.files.add(http.MultipartFile.fromBytes(
      'file', // Replace with your file name
      _file.readAsBytesSync(),
      filename: _file.path.split('/').last,
    ));

    final response = await request.send();

    if (response.statusCode == 200) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('File uploaded successfully')),
      );
    } else {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Error uploading file')),
      );
    }
  }
}
```
